from __future__ import annotations

import heapq


class DonguHatasi(ValueError):
    """Döngü tespit edildiğinde fırlatılan hata. `dongu` özniteliği döngüyü oluşturan
    paketleri alfabetik en küçük paketle başlayarak verir."""

    def __init__(self, dongu: list[str]):
        self.dongu = dongu
        super().__init__("Döngü tespit edildi: " + " -> ".join(dongu))


def kurulum_sirasi(deps: dict[str, list[str]]) -> list[str]:
    """Tüm paketleri, her paket kendi bağımlılıklarından sonra gelecek şekilde sıralar.
    O an kurulabilecek birden fazla paket varsa alfabetik en küçük önce gelir."""

    # Tüm paketleri topla (yalnızca bağımlılık olarak geçenler dahil)
    paketler: set[str] = set(deps)
    for bağımlılıklar in deps.values():
        paketler.update(bağımlılıklar)

    # Bağımlılık ilişkilerini temizle: aynı bağımlılık iki kez yazılmış olabilir
    bağımlılık_setleri: dict[str, set[str]] = {p: set() for p in paketler}
    for paket, bağımlılıklar in deps.items():
        bağımlılık_setleri[paket].update(bağımlılıklar)

    # Girme dereceleri: paket -> bağımlılık sayısı (girdi setinin eleman sayısı)
    girme_derecesi = {p: len(b) for p, b in bağımlılık_setleri.items()}

    # Bağımlılık -> bu bağımlılığı bekleyen paketler
    ters: dict[str, list[str]] = {p: [] for p in paketler}
    for paket, bağımlılıklar in bağımlılık_setleri.items():
        for b in bağımlılıklar:
            ters[b].append(paket)

    # Başlangıçta kurulabilenler: bağımlılığı olmayanlar (alfabetik min-heap)
    yigin = [p for p in paketler if girme_derecesi[p] == 0]
    heapq.heapify(yigin)

    sonuc: list[str] = []
    while yigin:
        paket = heapq.heappop(yigin)
        sonuc.append(paket)
        for bekleyen in ters[paket]:
            girme_derecesi[bekleyen] -= 1
            if girme_derecesi[bekleyen] == 0:
                heapq.heappush(yigin, bekleyen)

    if len(sonuc) != len(paketler):
        raise DonguHatasi(_döngü_bul(bağımlılık_setleri, paketler))

    return sonuc


def _döngü_bul(bağımlılıklar: dict[str, set[str]], paketler: set[str]) -> list[str]:
    """Bir döngüyü bulur ve döngüdeki alfabetik en küçük paketten başlayıp orada
    duran sırayı döndürür (a→b→c→a için ["a","b","c"])."""
    # Kalan (kurulamayan) alt grafik: girme derecesi > 0 olan paketler
    kalan = {p for p in paketler if any(b in paketler for b in bağımlılıklar.get(p, set()))}
    # Asıl kalanlar: bağımlılıklarından en az biri de kalanlarda olanlar.
    # Basit yaklaşımla: tüm bağımlılıkları kurulamayanlar değil, döngüdeki paketler
    # kendi bağımlılıklarının tamamı da kurulamamıştır; yinelemeyi kaldıralım.
    # Kaldı: her adım, kendi bağımlılıklarından en az biri hâlâ "kalan" olan paketler.
    def _kalir(p: str) -> bool:
        return any(b in kalan for b in bağımlılıklar.get(p, set()))

    while True:
        yeni = {p for p in kalan if _kalir(p)}
        if len(yeni) == len(kalan):
            break
        kalan = yeni

    # Kalan alt grafikte bir yere git: her p, bağımlılıkları ∩ kalan'dan birini seçer.
    # Döngü, bu "yere gitme" işleminin döngüye girmesiyle bulunur; sonra döngünün
    # en küçük elemanından başla.
    hedef: dict[str, str] = {}
    for p in kalan:
        baglar = sorted(b for b in bağımlılıklar[p] if b in kalan)
        hedef[p] = baglar[0] if baglar else p

    # Döngüyü bul
    renkler: dict[str, int] = {}  # 0: yeni, 1: ziyarette, 2: bitmiş
    def dfs(d: str) -> list[str] | None:
        renkler[d] = 1
        for b in sorted(bağımlılıklar.get(d, set())):
            if b not in kalan:
                continue
            if renkler.get(b, 0) == 0:
                if (döngü := dfs(b)) is not None:
                    return döngü
            elif renkler.get(b) == 1:
                # d -> b bağımlılığı (b, d'ye bağımlı değil: d, b'ye bağımlı)
                # döngü: b -> ... -> d -> b; listede "her paket sonraki pakete bağımlı"
                # d'ye bağımlı olanlar zinciri: b, ..., d
                döngü = [b]
                cur = d
                while cur != b:
                    döngü.append(cur)
                    cur = hedef[cur]
                döngü.reverse()
                return döngü
        renkler[d] = 2
        return None

    for p in sorted(kalan):
        if renkler.get(p, 0) == 0:
            if (döngü := dfs(p)) is not None:
                # Döngüyü alfabetik en küçük paketten başlayacak şekilde döndür
                min_paket = min(döngü)
                i = döngü.index(min_paket)
                döngü = döngü[i:] + döngü[:i]
                return döngü

    # Bu noktaya gelmemeli (kalan döngü içermek zorunda)
    raise AssertionError("kalan alt grafikte döngü bulunamadı")

