    bag_setleri: dict[str, set[str]] = {p: set() for p in paketler}
    for paket, baglar in deps.items():
        bag_setleri[paket].update(baglar)

    # Girme dereceleri: paket -> bağımlılık sayısı
    girme = {p: len(b) for p, b in bag_setleri.items()}

    # Bağımlılık -> bu bağımlılığı bekleyen paketler
    ters: dict[str, list[str]] = {p: [] for p in paketler}
    for paket, baglar in bag_setleri.items():
        for b in baglar:
            ters[b].append(paket)

    # Başlangıçta kurulabilenler: bağımlılığı olmayanlar (alfabetik min-heap)
