def _döngü_bul(bag_setleri: dict[str, set[str]], paketler: set[str]) -> list[str]:
    """Kalan (kurulamayan) alt grafikte bir döngü bulur ve döngüdeki alfabetik en
    küçük paketten başlayacak şekilde döndürür (a→b→c→a için ["a","b","c"])."""
    # Kurulamayan paketler: girme derecesi > 0 olanlar (Kahn sonrası)
    girme = {p: len(bag_setleri[p]) for p in paketler}
    ters: dict[str, list[str]] = {p: [] for p in paketler}
    for paket, baglar in bag_setleri.items():
        for b in baglar:
            ters[b].append(paket)
    kuyruk = [p for p in paketler if girme[p] == 0]
    kuyruk.sort()
    import collections
    k = collections.deque(kuyruk)
    while k:
        p = k.popleft()
        for bekleyen in ters[p]:
            girme[bekleyen] -= 1
            if girme[bekleyen] == 0:
                k.append(bekleyen)
    kalan = {p for p in paketler if girme[p] > 0}

    # En küçük kalan paketten DFS başlat (bağımlılıklar sıralı, iteratif).
    # İlk geri-kenar (stack'te olan bir pakete bağımlılık) bulunduğunda,
    # o paketten itibaren stack'in kendisi geçerli bir döngüdür:
    # stack = [a, ..., v] ve v, stack'teki u'ya bağımlıysa döngü [u, ..., v].
    start = min(kalan)
    baglar_sirali = {p: sorted(bag_setleri[p]) for p in kalan}
    yigin: list[tuple[str, int, list[str]]] = [(start, 0, [start])]
    while yigin:
        paket, i, yol = yigin[-1]
        if i == len(baglar_sirali[paket]):
            yigin.pop()
            continue
        yigin[-1] = (paket, i + 1, yol)
        b = baglar_sirali[paket][i]
        if b not in kalan:
            continue
        # b, mevcut yolda mı? (yolda => geri-kenar, döngü bulundu)
        if b in yol:
            idx = yol.index(b)
            return yol[idx:]
        # b zaten ziyaret edilmiş mi? (renk takibi yok; basit: yol'da değilse incele)
        yigin.append((b, 0, yol + [b]))
    # Buraya gelmemeli: kalan alt grafik döngü içermek zorunda.
    raise AssertionError("kalan alt grafikte döngü bulunamadı")

