def _döngü_bul(bag_setleri: dict[str, set[str]], paketler: set[str]) -> list[str]:
    """Kalan (kurulamayan) alt grafikte bir döngü bulur ve döngüdeki alfabetik en
    küçük paketten başlayacak şekilde döndürür (a→b→c→a için ["a","b","c"]).

    Kalan alt grafikte her paketin bağımlılık derecesi >= 1 olduğundan,
    en küçük kalan paketten bağımlılık kenarlarını takip ederek (her adımda
    bağımlılıkların alfabetik en küçük olanı seçilir) eninde sonunda bir
    pakete geri dönülür; geri dönülen nokta bir döngüdür. Bu döngü alfabetik
    en küçük paketten başlatıldığı için döngüdeki alfabetik en küçük pakete
    (yani kendisine) geri dönecektir, böylece döngü zaten doğru paketten
    başlar. (Yönlü döngüde her kenar bağımlılık kenarıdır, yani u->v için
    u, v'ye bağımlıdır.)"""
    import collections
    # Kurulamayan paketler: Kahn sonrası girme derecesi > 0 olanlar
    girme = {p: len(bag_setleri[p]) for p in paketler}
    ters: dict[str, list[str]] = {p: [] for p in paketler}
    for paket, baglar in bag_setleri.items():
        for b in baglar:
            ters[b].append(paket)
    k = collections.deque(sorted(p for p in paketler if girme[p] == 0))
    while k:
        p = k.popleft()
        for bekleyen in ters[p]:
            girme[bekleyen] -= 1
            if girme[bekleyen] == 0:
                k.append(bekleyen)
    kalan = {p for p in paketler if girme[p] > 0}

    # En küçük kalan paketten bağımlılıkları alfabetik en küçükle takip et
    baglar_sirali = {p: sorted(bag_setleri[p]) for p in kalan}
    start = min(kalan)
    yol: list[str] = [start]
    poz = {start: 0}
    paket = start
    while True:
        # paket'in kalan alt grafiğe giden, en küçük ziyaret-edilebilir bağımlılığı
        sonraki = None
        for b in baglar_sirali[paket]:
            if b in kalan:
                sonraki = b
                break
        if sonraki is None:
            # Kalan alt grafikte her paketin >=1 bağımlılığı olduğundan
            # ve bağımlılıkların da kalan içinde olması gerektiğinden bu
            # duruma gelmemeli; yine de güvenlik için.
            raise AssertionError("kalan alt grafikte döngü bulunamadı")
        if sonraki in poz:
            # Döngü bulundu: poz[sonraki]'den itibaren yol
            return yol[poz[sonraki]:]
        poz[sonraki] = len(yol)
        yol.append(sonraki)
        paket = sonraki

